import { MakeLogicType, afterMount, kea, path } from 'kea'
import { loaders } from 'kea-loaders'

import api from 'lib/api'
import { lemonToast } from 'lib/lemon-ui/LemonToast/LemonToast'

import { MetricsPipelineType } from './types'

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface pipelinesLogicValues {
    pipelines: MetricsPipelineType[]
    pipelinesLoading: boolean
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface pipelinesLogicActions {
    deletePipeline: (id: string) => string
    deletePipelineFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    deletePipelineSuccess: (
        pipelines: MetricsPipelineType[],
        payload?: string
    ) => {
        pipelines: MetricsPipelineType[]
        payload?: string
    }
    loadPipelines: () => any
    loadPipelinesFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    loadPipelinesSuccess: (
        pipelines: MetricsPipelineType[],
        payload?: any
    ) => {
        pipelines: MetricsPipelineType[]
        payload?: any
    }
}

export type pipelinesLogicType = MakeLogicType<pipelinesLogicValues, pipelinesLogicActions>

export const pipelinesLogic = kea<pipelinesLogicType>([
    path(['products', 'metrics', 'frontend', 'pipelines', 'pipelinesLogic']),
    loaders(({ values }) => ({
        pipelines: [
            [] as MetricsPipelineType[],
            {
                loadPipelines: async () => {
                    const response = await api.get('api/projects/@current/metrics_pipelines/')
                    return response.results as MetricsPipelineType[]
                },
                deletePipeline: async (id: string) => {
                    await api.delete(`api/projects/@current/metrics_pipelines/${id}/`)
                    lemonToast.success('Pipeline deleted')
                    return values.pipelines.filter((pipeline: MetricsPipelineType) => pipeline.id !== id)
                },
            },
        ],
    })),
    afterMount(({ actions }) => {
        actions.loadPipelines()
    }),
])
